"""Ticket triage — called by the /triage endpoint."""

import json

from gateway import llm


def triage(ticket):
    resp = llm.complete(
        model="gpt-4o-mini",
        temperature=0.7,
        prompt=f"""You are a support triage assistant for Acme Cloud.

Classify this ticket into exactly one queue: billing, onboarding, bug,
feature-request, abuse, other. Then write a friendly reply to the customer.

Customer plan: {ticket['plan_tier']}
Subject: {ticket['subject']}
Body: {ticket['body']}

Return JSON: {{"queue": ..., "draft_reply": ..., "confidence": 0-1}}
""",
    )
    return json.loads(resp.text)


def escalate_summary(thread):
    resp = llm.complete(
        model="gpt-4o-mini",
        temperature=0.7,
        prompt=f"""Summarize this support thread for a tier-2 engineer in
under 120 words. Be concrete about what the customer already tried.

Thread:
{thread}
""",
    )
    return resp.text
